const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  const validTipoObra = ['demolicion','reforma','obra_nueva','rehabilitacion'];
  const tipoOverride = body.tipo_obra_override && validTipoObra.includes(body.tipo_obra_override) ? body.tipo_obra_override : null;
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    tipo_obra_override: tipoOverride,
    anio_edificio_override: body.anio_edificio ? parseInt(body.anio_edificio, 10) : null,
    sistema_constructivo: body.sistema_constructivo || null,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const project = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!project || !project.id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}

// Coeficientes oficiales orientativos RD 105/2008 (LER 17). normativa_confidence 0.85.
const COEFICIENTES = {
  demolicion_completa: {
    ladrillo_ceramico:    { kg_por_m2: 540, ler_code: '170102', descripcion: 'Ladrillos' },
    hormigon:             { kg_por_m2: 360, ler_code: '170101', descripcion: 'Hormigon' },
    madera:               { kg_por_m2: 24,  ler_code: '170201', descripcion: 'Madera' },
    yeso:                 { kg_por_m2: 18,  ler_code: '170802', descripcion: 'Materiales yeso' },
    metal:                { kg_por_m2: 12,  ler_code: '170407', descripcion: 'Metales mezclados' },
    vidrio:               { kg_por_m2: 4,   ler_code: '170202', descripcion: 'Vidrio' },
    plastico:             { kg_por_m2: 3,   ler_code: '170203', descripcion: 'Plastico' },
    mezcla_no_peligrosa:  { kg_por_m2: 39,  ler_code: '170904', descripcion: 'Mezcla RCD no peligrosos' }
  },
  reforma: {
    ladrillo_ceramico:    { kg_por_m2: 95, ler_code: '170102', descripcion: 'Ladrillos' },
    yeso:                 { kg_por_m2: 22, ler_code: '170802', descripcion: 'Materiales yeso' },
    madera:               { kg_por_m2: 8,  ler_code: '170201', descripcion: 'Madera' },
    ceramica_sanitaria:   { kg_por_m2: 4,  ler_code: '170103', descripcion: 'Ceramica sanitaria' },
    metal:                { kg_por_m2: 3,  ler_code: '170407', descripcion: 'Metales mezclados' },
    mezcla_no_peligrosa:  { kg_por_m2: 18, ler_code: '170904', descripcion: 'Mezcla RCD no peligrosos' }
  }
};

// Mapeo project_type -> tipo_obra para coeficientes
const tipoMap = {
  reforma_integral: 'reforma',
  redistribucion:   'reforma',
  cambio_uso:       'rehabilitacion',
  adecuacion:       'reforma',
  apoyo_tecnico:    'reforma',
  otro:             'reforma'
};
const tipoObra = sess.tipo_obra_override || tipoMap[project.project_type] || 'reforma';

// Para coeficientes: mapear demolicion-completa o reforma-default
const coefKey = tipoObra === 'demolicion' ? 'demolicion_completa' : 'reforma';
const coef = COEFICIENTES[coefKey];

const superficie = project.property_area_m2 ? parseFloat(project.property_area_m2) : 0;
if (superficie <= 0) {
  return [{ json: { _error: 'NO_SUPERFICIE', _status: 422, _details: 'property_area_m2 requerido para calcular RCD' } }];
}

// Calcular estimacion por fraccion
const estimacion = [];
let totalKg = 0;
for (const [key, c] of Object.entries(coef)) {
  const kg = c.kg_por_m2 * superficie;
  estimacion.push({
    fraccion: key,
    descripcion: c.descripcion,
    ler_code: c.ler_code,
    kg_total: Math.round(kg),
    toneladas: Math.round((kg / 1000) * 1000) / 1000,
    metros_cubicos: Math.round((kg / 1500) * 100) / 100
  });
  totalKg += kg;
}
const totalToneladas = Math.round((totalKg / 1000) * 1000) / 1000;

// Alerta amianto: edificios < 2002 con demolicion (Real Decreto 396/2006)
const anioEdificio = sess.anio_edificio_override || project.edad_edificio;
const alertasPeligrosos = [];
if (tipoObra === 'demolicion' && anioEdificio && anioEdificio < 2002) {
  alertasPeligrosos.push({
    tipo: 'amianto',
    severidad: 'critica',
    descripcion: 'Edificio anterior a 2002 con demolicion: obligatorio plan especifico amianto (RD 396/2006). Inspeccion previa por empresa RERA.',
    citation: 'RD 396/2006 sobre disposiciones minimas seguridad amianto',
    accion_requerida: 'Contratar empresa inscrita RERA para inspeccion + plan trabajo presentado a Autoridad Laboral'
  });
}
if (tipoObra === 'demolicion' && anioEdificio && anioEdificio < 1985) {
  alertasPeligrosos.push({
    tipo: 'plomo',
    severidad: 'alta',
    descripcion: 'Edificio anterior a 1985: posibles tuberias de plomo y pinturas con plomo. Analisis previo recomendado.',
    citation: 'RD 140/2003 calidad agua + RD 374/2001 agentes quimicos',
    accion_requerida: 'Cata previa de instalaciones agua y pinturas. Si plomo confirmado, gestion via gestor autorizado.'
  });
}

return [{ json: {
  ...sess,
  project: {
    id: project.id,
    name: project.name,
    project_type: project.project_type,
    location_province: project.location_province,
    location_city: project.location_city,
    property_type: project.property_type,
    superficie_m2: superficie,
    notes: project.notes,
    edad_edificio: anioEdificio,
    sistema_constructivo: sess.sistema_constructivo || project.sistema_constructivo
  },
  tipo_obra: tipoObra,
  estimacion_residuos: estimacion,
  total_toneladas: totalToneladas,
  total_kg: Math.round(totalKg),
  alertas_peligrosos: alertasPeligrosos,
  normativa_confidence: 0.85
}}];

const ctx = $input.first().json;
const project = ctx.project;

const systemPrompt = `Eres agent_rcd, tecnico en gestion de residuos de construccion y demolicion conforme al RD 105/2008 y normativa autonomica espanola.

REGLAS DE ORO:
- Los coeficientes y totales ya estan calculados de forma determinista. NO los modifiques.
- Tu tarea: redactar plan_gestion (separacion en obra, almacenamiento, transporte) y sugerir gestores autorizados genericos por fraccion.
- Si hay alertas_peligrosos, integrarlas en plan_gestion con seccion especifica.
- normativa_confidence ya viene calculada (0.85 con coeficientes oficiales).
- DEVUELVE SOLO JSON valido, sin texto fuera del JSON.
- El arquitecto firma. Tu propones.`;

const alertasText = ctx.alertas_peligrosos.length > 0
  ? '
ALERTAS PELIGROSOS DETECTADAS:
' + ctx.alertas_peligrosos.map(a => `- [${a.severidad}] ${a.tipo}: ${a.descripcion}`).join('
')
  : '
No se detectaron residuos peligrosos automaticamente. Verificar manualmente in situ.';

const userPrompt = `PROYECTO:
- Nombre: ${project.name}
- Tipo de obra: ${ctx.tipo_obra}
- Tipo inmueble: ${project.property_type ?? '?'}
- Superficie intervencion: ${project.superficie_m2} m2
- Ubicacion: ${project.location_city ?? '?'}, ${project.location_province ?? '?'}
- Anio edificio: ${project.edad_edificio ?? 'desconocido'}
- Sistema constructivo: ${project.sistema_constructivo ?? 'no especificado'}
- Notas arquitecto: ${project.notes ? project.notes.slice(0, 400) : '(sin notas)'}

ESTIMACION RESIDUOS YA CALCULADA (${ctx.total_toneladas} Tn totales):
${JSON.stringify(ctx.estimacion_residuos, null, 2)}
${alertasText}

TAREA:
1. Redacta el PLAN DE GESTION: como se separa cada fraccion en obra, almacenamiento intermedio, transporte y entrega a gestor.
2. Sugiere GESTORES AUTORIZADOS por fraccion principal (descripcion generica + tipo de gestor, no nombres concretos a menos que sean obvios).
3. Estima COSTE GESTION en EUR (rangos orientativos por Tm: inertes 5-15 EUR/Tm, mezclados 30-60 EUR/Tm, peligrosos 200-500 EUR/Tm).
4. Si hay alertas_peligrosos, anade SECCION ESPECIFICA en plan_gestion con pasos legales.
5. Indica DOCUMENTOS A GENERAR para licencia (Estudio Gestion RCD, Plan Gestion RCD).

OUTPUT (JSON estricto):
{
  "plan_gestion": {
    "separacion_en_obra": ["..."],
    "almacenamiento": "...",
    "transporte": "...",
    "seccion_peligrosos": "..."
  },
  "gestores_recomendados": [
    { "fraccion": "...", "tipo_gestor": "...", "observaciones": "..." }
  ],
  "coste_gestion_estimado_eur": 1240,
  "documentos_a_generar": ["Estudio_Gestion_RCD.pdf", "Plan_Gestion_RCD.pdf"],
  "observaciones_tecnicas": "..."
}`;

return [{ json: {
  ...ctx,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 1200,
    response_format: { type: 'json_object' }
  }
}}];

