const llm = $input.first()?.json;
const ctx = $('Build Context + Calculate').first().json;
const project = ctx.project;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message } }];
}
const usage = llm?.usage || {};
// Combinar todo en draft_content (jsonb completo)
const draftContent = {
  estimacion_residuos: ctx.estimacion_residuos,
  total_toneladas: ctx.total_toneladas,
  total_kg: ctx.total_kg,
  alertas_peligrosos: ctx.alertas_peligrosos,
  plan_gestion: parsed.plan_gestion || {},
  gestores_recomendados: parsed.gestores_recomendados || [],
  coste_gestion_estimado_eur: parsed.coste_gestion_estimado_eur || null,
  documentos_a_generar: parsed.documentos_a_generar || [],
  observaciones_tecnicas: parsed.observaciones_tecnicas || '',
  normativa_confidence: ctx.normativa_confidence,
  citation_source: 'RD 105/2008 + Plan Estatal Marco Gestion Residuos PEMAR'
};
return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: project.id,
  request_id: ctx.request_id,
  tipo_obra: ctx.tipo_obra,
  superficie_m2: project.superficie_m2,
  estimacion_residuos: ctx.estimacion_residuos,
  total_toneladas: ctx.total_toneladas,
  plan_gestion: parsed.plan_gestion || {},
  gestores_recomendados: parsed.gestores_recomendados || [],
  coste_gestion_estimado_eur: parsed.coste_gestion_estimado_eur || null,
  alertas_peligrosos: ctx.alertas_peligrosos,
  draft_content: draftContent,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

